import { relations } from "drizzle-orm";
import {
  date,
  decimal,
  index,
  int,
  mysqlEnum,
  mysqlTable,
  timestamp,
  unique,
  varchar,
} from "drizzle-orm/mysql-core";
import { OTHER_DEDUCTION_TYPES } from "../irpf/deductions";
import { EXPENSE_CATEGORIES } from "../irpf/expenses";
import { user } from "./auth-schema";

// auth-schema.ts is generated by `auth generate`, so app tables live here.
export * from "./auth-schema";

function money(name: string) {
  return decimal(name, { precision: 12, scale: 2, mode: "number" });
}

export const employment = mysqlTable("employment", {
  id: varchar("id", { length: 36 }).primaryKey(),
  userId: varchar("user_id", { length: 36 })
    .notNull()
    .references(() => user.id, { onDelete: "cascade" }),
  name: varchar("name", { length: 120 }).notNull(),
  createdAt: timestamp("created_at", { fsp: 3 }).defaultNow().notNull(),
});

export const monthlyEntry = mysqlTable(
  "monthly_entry",
  {
    id: varchar("id", { length: 36 }).primaryKey(),
    userId: varchar("user_id", { length: 36 })
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    employmentId: varchar("employment_id", { length: 36 })
      .notNull()
      .references(() => employment.id, { onDelete: "cascade" }),
    year: int("year").notNull(),
    month: int("month").notNull(),
    income: money("income").notNull(),
    officialPension: money("official_pension").default(0).notNull(),
    dependents: int("dependents").default(0).notNull(),
    alimony: money("alimony").default(0).notNull(),
    withheldTax: money("withheld_tax").default(0).notNull(),
    createdAt: timestamp("created_at", { fsp: 3 }).defaultNow().notNull(),
    updatedAt: timestamp("updated_at", { fsp: 3 })
      .defaultNow()
      .$onUpdate(() => new Date())
      .notNull(),
  },
  (table) => [
    unique("monthly_entry_employment_period_unique").on(
      table.userId,
      table.employmentId,
      table.year,
      table.month,
    ),
  ],
);

export const otherDeduction = mysqlTable("other_deduction", {
  id: varchar("id", { length: 36 }).primaryKey(),
  entryId: varchar("entry_id", { length: 36 })
    .notNull()
    .references(() => monthlyEntry.id, { onDelete: "cascade" }),
  type: mysqlEnum("type", OTHER_DEDUCTION_TYPES).notNull(),
  amount: money("amount").notNull(),
});

export const expense = mysqlTable(
  "expense",
  {
    id: varchar("id", { length: 36 }).primaryKey(),
    userId: varchar("user_id", { length: 36 })
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    year: int("year").notNull(),
    category: mysqlEnum("category", EXPENSE_CATEGORIES).notNull(),
    description: varchar("description", { length: 255 }).notNull(),
    beneficiary: varchar("beneficiary", { length: 120 }).notNull(),
    date: date("date", { mode: "string" }).notNull(),
    amount: money("amount").notNull(),
    createdAt: timestamp("created_at", { fsp: 3 }).defaultNow().notNull(),
  },
  (table) => [index("expense_user_year_idx").on(table.userId, table.year)],
);

export const monthlyEntryRelations = relations(
  monthlyEntry,
  ({ many, one }) => ({
    user: one(user, {
      fields: [monthlyEntry.userId],
      references: [user.id],
    }),
    employment: one(employment, {
      fields: [monthlyEntry.employmentId],
      references: [employment.id],
    }),
    otherDeductions: many(otherDeduction),
  }),
);

export const otherDeductionRelations = relations(otherDeduction, ({ one }) => ({
  entry: one(monthlyEntry, {
    fields: [otherDeduction.entryId],
    references: [monthlyEntry.id],
  }),
}));
